// Mass Effect Archipelago Launcher: downloads each game's world, bridge and mod from that game's GitHub releases
// (Releases.cs), installs them with backups (Installer.cs, see Profiles.cs), writes the player's YAML into Archipelago's
// Players folder and launches the game. Seeds are still generated by Archipelago and hosted on archipelago.gg.
//
// Payload (the files Installer copies) for a game, first found: --payload, a folder named after the game next to the exe
// (ME1\, ME2\, ME3\: offline or test builds), the newest download in %LOCALAPPDATA%\MassEffectAPSetup\downloads.
//
// Command line (tests; output goes to the calling console):
//   --install <ME1|ME2|ME3> --game <LE folder> --ap <Archipelago folder> [--payload <dir>] [--state <dir>] [--keep-movie <file>]...
//   --uninstall <ME1|ME2|ME3> --game ... --ap ... [--payload <dir>] [--state <dir>]
//   --check <ME1|ME2|ME3> --game ... --ap ... [--payload <dir>]     (what Launch would refuse; exit code 1 if anything)
//   --latest <ME1|ME2|ME3|launcher>                                (the newest GitHub release and the files the launcher would take)
//   --fetch <ME1|ME2|ME3>                                          (download the newest release into the cache; prints the payload folder)
//   --le1-toc <BioGame folder> <out file>                          (the LE1 game TOC this app writes)
//   --toc-list <PCConsoleTOC.bin>
//   --write-yaml <ME1|ME2|ME3> <file> [slot] [preset]
using System.Runtime.InteropServices;
using System.Text;
using System.Windows;

namespace APSetup;

static class Program
{
    public const string AppName = "Mass Effect Archipelago Launcher";
    public static string Version => typeof(Program).Assembly.GetName().Version is { } v ? $"{v.Major}.{v.Minor}.{v.Build}" : "0";

    [DllImport("kernel32.dll")] static extern bool AttachConsole(int processId);

    [STAThread]
    static int Main(string[] args)
    {
        if (args.Length > 0 && args[0].StartsWith("--") && args[0] != "--screenshot")
        {
            AttachConsole(-1);
            try { return Cli(args); }
            catch (Exception ex) { Console.Error.WriteLine("ERROR: " + ex.Message); return 2; }
        }
        var app = new Application { ShutdownMode = ShutdownMode.OnMainWindowClose };
        app.DispatcherUnhandledException += (_, e) => { Crash(e.Exception); e.Handled = true; };
        app.Resources.MergedDictionaries.Add(new ResourceDictionary { Source = new Uri("pack://application:,,,/Mass Effect Archipelago Launcher;component/Theme.xaml") });
        if (args.Length > 1 && args[0] == "--screenshot") return Screenshot(app, args);
        try { app.Run(new MainWindow()); }
        catch (Exception ex) { Crash(ex); return 1; }
        return 0;
    }

    // --screenshot <out.png> [ME1|ME2|ME3] [deploy|folders|options|intel]: renders the window off screen, without taking focus
    // (for docs and reviewing the look). Nothing is installed or changed.
    static int Screenshot(Application app, string[] args)
    {
        var window = new MainWindow { Left = -4000, Top = 0, ShowActivated = false, ShowInTaskbar = false, WindowStartupLocation = WindowStartupLocation.Manual };
        if (args.Length > 2) window.SelectGame(args[2]);
        if (args.Length > 3) window.SelectTab(args[3]);
        var timer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(4) };
        timer.Tick += (_, _) =>
        {
            timer.Stop();
            var root = (FrameworkElement)window.Content;
            var bitmap = new System.Windows.Media.Imaging.RenderTargetBitmap((int)root.ActualWidth, (int)root.ActualHeight, 96, 96, System.Windows.Media.PixelFormats.Pbgra32);
            bitmap.Render(root);
            var png = new System.Windows.Media.Imaging.PngBitmapEncoder();
            png.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bitmap));
            using (var file = File.Create(args[1])) png.Save(file);
            window.Close();
        };
        window.Loaded += (_, _) => timer.Start();
        app.Run(window);
        return 0;
    }

    // Shown, and kept for bug reports in %LOCALAPPDATA%\MassEffectAPSetup\launcher-error.log.
    static void Crash(Exception ex)
    {
        try { File.AppendAllText(Path.Combine(Path.GetDirectoryName(Releases.CacheRoot), "launcher-error.log"), $"{DateTime.Now:u} {ex}\n\n"); }
        catch (Exception) { }
        MessageBox.Show(ex.Message, AppName, MessageBoxButton.OK, MessageBoxImage.Error);
    }

    // The payload folder for a game (see the header), or null if there is none yet.
    public static string Payload(GameProfile profile, string explicitDir = null)
    {
        if (explicitDir != null) return explicitDir;
        var bundled = Path.Combine(AppContext.BaseDirectory, profile.Id);
        if (Directory.Exists(bundled)) return bundled;
        return Releases.Cached(profile.Id)?.Dir;
    }

    static int Cli(string[] args)
    {
        string Arg(string name, string fallback = null)
        {
            int i = Array.IndexOf(args, name);
            return i >= 0 && i + 1 < args.Length ? args[i + 1] : fallback;
        }
        GameProfile Profile(string id) => GameProfile.All.FirstOrDefault(p => p.Id.Equals(id, StringComparison.OrdinalIgnoreCase))
            ?? throw new ArgumentException($"unknown game {id} (ME1, ME2 or ME3)");
        Installer Make(GameProfile p) => new(p, Arg("--game"), Arg("--ap"),
            Payload(p, Arg("--payload")) ?? throw new InvalidOperationException($"no {p.Id} payload: run --fetch {p.Id} or pass --payload"),
            Arg("--state", Installer.DefaultStateDir(p)));
        switch (args[0])
        {
            case "--install":
            {
                var installer = Make(Profile(args[1]));
                var options = new Installer.Options();
                for (int i = 0; i < args.Length - 1; i++)
                    if (args[i] == "--keep-movie") options.KeepMovies.Add(args[i + 1]);
                installer.Install(options);
                installer.Log.ForEach(Console.WriteLine);
                return 0;
            }
            case "--uninstall":
            {
                var installer = Make(Profile(args[1]));
                installer.Uninstall();
                installer.Log.ForEach(Console.WriteLine);
                return 0;
            }
            case "--check":
            {
                var problems = Make(Profile(args[1])).LaunchProblems();
                problems.ForEach(Console.WriteLine);
                Console.WriteLine(problems.Count == 0 ? "ready to launch" : $"{problems.Count} problem(s)");
                return problems.Count == 0 ? 0 : 1;
            }
            case "--latest":
            {
                Releases.ResolveProjects().GetAwaiter().GetResult();
                var project = args[1].Equals("launcher", StringComparison.OrdinalIgnoreCase) ? Releases.LauncherProject : Releases.Projects[Profile(args[1]).Id];
                var release = Releases.Latest(project).GetAwaiter().GetResult();
                if (release == null) { Console.WriteLine($"{project}: no release yet"); return 1; }
                Console.WriteLine($"{project} {release.Tag} ({release.Released:yyyy-MM-dd})");
                var sums = Releases.Sums(release).GetAwaiter().GetResult();
                foreach (var asset in Releases.PayloadAssets(release))
                    Console.WriteLine($"  {asset.Name}  {(sums.TryGetValue(asset.Name, out var h) ? "sha256 " + h[..16] + "..." : "no sha256")}");
                return 0;
            }
            case "--fetch":
            {
                Releases.ResolveProjects().GetAwaiter().GetResult();
                var profile = Profile(args[1]);
                var release = Releases.Latest(Releases.Projects[profile.Id]).GetAwaiter().GetResult()
                              ?? throw new InvalidOperationException($"{Releases.Projects[profile.Id]} has no release yet");
                var dir = Releases.Fetch(profile, release, new Progress<(double, string)>(), Console.WriteLine).GetAwaiter().GetResult();
                Console.WriteLine(dir);
                return 0;
            }
            case "--le1-toc":
                File.WriteAllBytes(args[2], Installer.Le1Toc(args[1]));
                Console.WriteLine($"wrote {args[2]}");
                return 0;
            case "--toc-list":   // <PCConsoleTOC.bin>: one "<size> <name>" line per entry, sorted (to compare TOCs)
                foreach (var line in new LegendaryExplorerCore.Unreal.TOCBinFile(args[1]).GetAllEntries()
                             .Select(e => $"{e.size} {e.name}").Order(StringComparer.OrdinalIgnoreCase))
                    Console.WriteLine(line);
                return 0;
            case "--write-yaml":
            {
                var profile = Profile(args[1]);
                var model = OptionsModel.For(profile, Payload(profile, Arg("--payload")));
                var preset = args.Length > 4 && !args[4].StartsWith("--") ? args[4] : "Default";
                model.ApplyPreset(preset);
                File.WriteAllText(args[2], model.BuildYaml(args.Length > 3 && !args[3].StartsWith("--") ? args[3] : "Shepard", preset, AppName, Version),
                                  new UTF8Encoding(false));
                return 0;
            }
        }
        throw new ArgumentException("unknown command " + args[0]);
    }
}
